#pragma once

#include <cstddef>
#include <cmath>
#include <immintrin.h>
<omp.h>

namespace baseline {

inline std::size_t idx(const std::size_t i, const std::size_t j, const std::size_t n) {
    return i * n + j;
}

inline void gauss_seidel_poisson_sweep(
    double* psi, const double* omega, const std::size_t n,
    const double h, const std::size_t sweeps = 1) {
    const double h2 = h * h;
    for (std::size_t sweep = 0; sweep < sweeps; ++sweep) {
        // Update black cells (i+j even)
        #pragma omp parallel for schedule(static)
        for (std::size_t i = 1; i + 1 < n; ++i) {
            for (std::size_t j = 1; j + 1 < n; ++j) {
                if (((i + j) & 1) == 0) { // black
                    psi[idx(i, j, n)] = 0.25 * (
                        psi[idx(i + 1, j, n)] + psi[idx(i - 1, j, n)] +
                        psi[idx(i, j + 1, n)] + psi[idx(i, j - 1, n)] +
                        h2 * omega[idx(i, j, n)]
                    );
                }
            }
        }
        // Update white cells (i+j odd)
        #pragma omp parallel for schedule(static)
        for (std::size_t i = 1; i + 1 < n; ++i) {
            for (std::size_t j = 1; j + 1 < n; ++j) {
                if (((i + j) & 1) == 1) { // white
                    psi[idx(i, j, n)] = 0.25 * (
                        psi[idx(i + 1, j, n)] + psi[idx(i - 1, j, n)] +
                        psi[idx(i, j + 1, n)] + psi[idx(i, j - 1, n)] +
                        h2 * omega[idx(i, j, n)]
                    );
                }
            }
        }
    }
}

inline void vorticity_transport_step(
    double* omega_new,
    const double* omega,
    const double* psi,
    const std::size_t n,
    const double h,
    const double dt,
    const double re) 
{
    const double inv_2h = 0.5 / h;
    const double inv_h2 = 1.0 / (h * h);
    const double inv_re = 1.0 / re;
    constexpr std::size_t VF = 4; // AVX2 double width

    #pragma omp parallel for schedule(static)
    for (std::size_t i = 1; i + 1 < n; ++i) {
        const std::size_t i_n   = i * n;
        const std::size_t im1_n = (i - 1) * n;
        const std::size_t ip1_n = (i + 1) * n;

        std::size_t j = 1;
        // Vectorized inner loop
        for (; j + VF <= n - 1; j += VF) {
            // Load psi values needed for u and v
            __m256d psi_jm1 = _mm256_loadu_pd(psi + i_n + (j - 1));
            __m256d psi_j   = _mm256_loadu_pd(psi + i_n + j);
            __m256d psi_jp1 = _mm256_loadu_pd(psi + i_n + (j + 1));
            __m256d psi_im1_j = _mm256_loadu_pd(psi + im1_n + j);
            __m256d psi_ip1_j = _mm256_loadu_pd(psi + ip1_n + j);

            // Load omega values needed for derivatives and Laplacian
            __m256d om_jm1 = _mm256_loadu_pd(omega + i_n + (j - 1));
            __m256d om_j   = _mm256_loadu_pd(omega + i_n + j);
            __m256d om_jp1 = _mm256_loadu_pd(omega + i_n + (j + 1));
            __m256d om_im1_j = _mm256_loadu_pd(omega + im1_n + j);
            __m256d om_ip1_j = _mm256_loadu_pd(omega + ip1_n + j);

            // u = (psi[j+1] - psi[j-1]) * inv_2h
            __m256d u = _mm256_sub_pd(psi_jp1, psi_jm1);
            u = _mm256_mul_pd(u, _mm256_set1_pd(inv_2h));

            // v = -(psi[i+1][j] - psi[i-1][j]) * inv_2h
            __m256d v = _mm256_sub_pd(psi_ip1_j, psi_im1_j);
            v = _mm256_mul_pd(v, _mm256_set1_pd(-inv_2h));

            // domega/dx = (omega[i+1][j] - omega[i-1][j]) * inv_2h
            __m256d domega_dx = _mm256_sub_pd(om_ip1_j, om_im1_j);
            domega_dx = _mm256_mul_pd(domega_dx, _mm256_set1_pd(inv_2h));

            // domega/dy = (omega[i][j+1] - omega[i][j-1]) * inv_2h
            __m256d domega_dy = _mm256_sub_pd(om_jp1, om_jm1);
            domega_dy = _mm256_mul_pd(domega_dy, _mm256_set1_pd(inv_2h));

            // advection = u*domega/dx + v*domega/dy
            __m256d advection = _mm256_add_pd(
                _mm256_mul_pd(u, domega_dx),
                _mm256_mul_pd(v, domega_dy)
            );

            // Laplacian: (ω[i+1,j]+ω[i-1,j]+ω[i,j+1]+ω[i,j-1]-4*ω[i,j]) * inv_h2
            __m256d sum = _mm256_add_pd(
                _mm256_add_pd(om_ip1_j, om_im1_j),
                _mm256_add_pd(om_jp1, om_jm1)
            );
            __m256d four_om = _mm256_mul_pd(om_j, _mm256_set1_pd(4.0));
            __m256d laplacian = _mm256_sub_pd(sum, four_om);
            laplacian = _mm256_mul_pd(laplacian, _mm256_set1_pd(inv_h2));

            // ω_new = ω + dt * ( (1/Re)*Laplacian - advection )
            __m256d term = _mm256_sub_pd(
                _mm256_mul_pd(laplacian, _mm256_set1_pd(inv_re)),
                advection
            );
            term = _mm256_mul_pd(term, _mm256_set1_pd(dt));
            __m256d omega_new_val = _mm256_add_pd(om_j, term);

            // Store result
            _mm256_storeu_pd(omega_new + i_n + j, omega_new_val);
        }

        // Scalar remainder
        for (; j < n - 1; ++j) {
            const std::size_t c = idx(i, j, n);

            const double u = (psi[idx(i, j + 1, n)] - psi[idx(i, j - 1, n)]) * inv_2h;
            const double v = -(psi[idx(i + 1, j, n)] - psi[idx(i - 1, j, n)]) * inv_2h;

            const double domega_dx = (omega[idx(i + 1, j, n)] - omega[idx(i - 1, j, n)]) * inv_2h;
            const double domega_dy = (omega[idx(i, j + 1, n)] - omega[idx(i, j - 1, n)]) * inv_2h;
            const double advection = u * domega_dx + v * domega_dy;

            const double laplacian_omega = (
                omega[idx(i + 1, j, n)] + omega[idx(i - 1, j, n)] +
                omega[idx(i, j + 1, n)] + omega[idx(i, j - 1, n)] -
                4.0 * omega[c]
            ) * inv_h2;

            omega_new[c] = omega[c] + dt * (inv_re * laplacian_omega - advection);
        }
    }
}

