                        psi[idx(i, j + 1, n)] + psi[idx(i, j - 1, n)] +
                        h2 * omega[idx(i, j, n)]
                    );
                }
            }
        }
        // Black cells: (i + j) % 2 == 1
        #pragma omp parallel for schedule(static)
        for (std::size_t i = 1; i < n - 1; ++i) {
            for (std::size_t j = 1; j < n - 1; ++j) {
                if (((i + j) & 1) == 1) { // black
                    psi[idx(i, j, n)] = 0.25 * (
                        psi[idx(i + 1, j, n)] + psi[idx(i - 1, j, n)] +
                        psi[idx(i, j + 1, n)] + psi[idx(i, j - 1, n)] +
                        h2 * omega[idx(i, j, n)]
                    );
                }
            }
        }
    }
